import { readFileSync } from "fs";

const s = readFileSync(0, "utf8").trim();
const vowels = new Set(["a", "i", "u", "e", "o"]);

let count = 0;
for (const c of s) {
  if (vowels.has(c)) count++;
}
console.log(count);
